def release_frame_callback(self, owner, callback) -> bool:
    """Inactive native scenes retain their work for their next frame."""
    if not self.is_current:
        return False
    return self.app.workspace_sessions.release_frame_callback(owner, callback)

def advance_spinner(self, phase: int) -> None:
    if self._spinner_phase == phase or not self.busy:
        return
    self._spinner_phase = phase
    if self._thread_presentation is not None:
        self.paint_thread_frame(self._thread_presentation)

def painted_rows(self):
    """Borrow this panel's rows from the original native scene.

        Each row owns whether its prepared status has an animated frame.
        """
    from toad.widgets.comms_sidebar import CommsRow
    for row in self.screen._compositor.visible_widgets:
        if isinstance(row, CommsRow) and row.is_navigation_row() and (row.sidebar_owner() is self):
            yield row
